        if(preg_match('/^(?:السلام\s+عليكم|سلام|اهلا|أهلا|هلا|الو|ألو|hello|hi|hey)[\s.!؟]*$/ui',$t))return 'أهلًا يا باشمهندس، رامي معك. قول لي المطلوب.';
