    public static function refreshSummary(int $sessionId):void{
        $history=ConversationService::history($sessionId,max(16,min(36,(int)setting('context.history_limit','28'))));if(count($history)<6)return;$ramy=AgentService::bySlug('ramy');if(!AgentService::runnable($ramy))return;$lines=[];foreach($history as $m)$lines[]=(($m['sender_type']==='owner'?'المالك':($m['sender_type']==='customer'?'العميل':'رامي')).': '.pb_substr((string)$m['body_text'],0,700));$schema=['type'=>'object','additionalProperties'=>false,'properties'=>['summary'=>['type'=>'string']],'required'=>['summary']];try{$r=AiGateway::json($ramy,'لخص السياق العملي فقط: المشروع المقصود، المطلوب، القرارات، آخر حالة، وما الذي ينتظر التنفيذ. لا تحفظ دردشة غير مهمة ولا أسرار.',[['role'=>'user','content'=>implode("\n",$lines)]],$schema,'context_summary',1600);db()->prepare('UPDATE conversation_sessions SET context_summary=? WHERE id=?')->execute([(string)$r['data']['summary'],$sessionId]);}catch(Throwable){return;}
    }
    private static function runLog(array $a,array $r,string $summary):void{try{db()->prepare("INSERT INTO agent_runs(agent_id,state,provider_key,model,input_tokens,output_tokens,summary,completed_at) VALUES (?,'completed',?,?,?,?,?,NOW())")->execute([$a['id'],$a['provider_key'],$r['model']??$a['model'],$r['input_tokens']??0,$r['output_tokens']??0,$summary]);}catch(Throwable){}}
